export const getPageNameByPath = (path) => {
  // Main routes
  const mainRoutes = {
    '/': 'Главная',
    '/news': 'Новости',
    '/specialities': 'Специальности',
    '/opendoorsEvent': 'День открытых дверей',
    '/timetable': 'Расписание',
    '/introductory': 'Приемная кампания',
    '/distance': 'Дистанционное обучение',
    '/club': 'Клуб',
    '/about': 'О нас',
    '/documents': 'Документы',
    '/professionalitet': 'Профессионалитет',
    '/terms/data-processing': 'Обработка данных',
    '/privacy': 'Политика конфиденциальности'
  };

  if (mainRoutes[path]) {
    return mainRoutes[path];
  }

  // Specialities routes
  if (path.startsWith('/specialities/')) {
    const specialityRoutes = {
      '/specialities/software-development': 'Разработка ПО',
      '/specialities/information-systems-programming': 'Программирование ИС',
      '/specialities/car-maintenance': 'Обслуживание автомобилей',
      '/specialities/electrical-installation': 'Электромонтаж',
      '/specialities/electrical-equipment-maintenance': 'Обслуживание электрооборудования',
      '/specialities/water-supply-and-sewerage': 'Водоснабжение и канализация',
      '/specialities/engine-systems-maintenance': 'Обслуживание двигателей',
      '/specialities/computer-networks': 'Компьютерные сети',
      '/specialities/computer-systems-complexes': 'Компьютерные системы',
      '/specialities/network-administration': 'Сетевое администрирование',
      '/specialities/physical-education': 'Физическое воспитание',
      '/specialities/mechatronics-robotics': 'Мехатроника и робототехника',
      '/specialities/test': 'Тест специальности'
    };

    return specialityRoutes[path] || 'Специальность';
  }

  // News detail page
  if (path.startsWith('/news/')) {
    return 'Новость';
  }

  return 'Страница';
};