import React from 'react';

const HeroImage = ({ imageRef, collegeImage }) => {
  return (
    <div className="hero-section__image" ref={imageRef}>
      <img
        src={collegeImage}
        alt="Здание Донецкого политехнического колледжа"
        loading="eager"
      />
    </div>
  );
};

export default HeroImage;