import React, { useState, useEffect, useRef } from 'react';
import './HeroSection.scss';
import SubmitDocumentsModal from '../../../../components/ui/SubmitDocumentsModal/SubmitDocumentsModal';
import collegeImage from '../../../../assets/img/img/college/1.jpg';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import HeroContent from './components/HeroContent';
import HeroImage from './components/HeroImage';
import ScrollArrow from './components/ScrollArrow';
import { Particles } from "react-tsparticles";
import { loadSlim } from "tsparticles-slim";

gsap.registerPlugin(ScrollTrigger);

const HeroSection = () => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  const heroRef = useRef(null);
  const textRef = useRef(null);
  const imageRef = useRef(null);
  const titleGreenRef = useRef(null);
  const titleBlueRef = useRef(null);
  const descriptionRef = useRef(null);
  const buttonsRef = useRef(null);
  const scrollArrowRef = useRef(null);
  const particlesRef = useRef(null);

  const particlesInit = async (engine) => {
    await loadSlim(engine);
  };

  useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth <= 768);
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);

    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const handleOpenModal = () => {
    setIsModalOpen(true);
    document.body.style.overflow = 'hidden';
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    document.body.style.overflow = '';
  };

  const scrollToNextSection = () => {
    const nextSection = document.querySelector('.hero-section').nextElementSibling;
    if (nextSection) {
      nextSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  useEffect(() => {
    if (isMobile || !heroRef.current) return;

    initializeAnimations();
  }, [isMobile]);

  const initializeAnimations = () => {
    ScrollTrigger.getAll().forEach(trigger => trigger.kill());

    const tl = gsap.timeline({
      defaults: { ease: "power3.out" }
    });

    tl.fromTo(titleGreenRef.current,
      { y: 50, opacity: 0 },
      { y: 0, opacity: 1, duration: 0.7 }
    )
      .fromTo(titleBlueRef.current,
        { y: 30, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.6 },
        "-=0.4"
      )
      .fromTo(descriptionRef.current,
        { y: 25, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.5 },
        "-=0.3"
      )
      .fromTo(buttonsRef.current,
        { y: 20, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.5 },
        "-=0.2"
      )
      .fromTo(imageRef.current,
        { x: 50, opacity: 0 },
        { x: 0, opacity: 1, duration: 0.8, ease: "power2.out" },
        "-=1.2"
      )
      .fromTo(scrollArrowRef.current,
        { y: -20, opacity: 0 },
        { y: 0, opacity: 1, duration: 0.5 },
        "-=0.3"
      )
      .fromTo(particlesRef.current,
        { opacity: 0 },
        { opacity: 1, duration: 1.2 },
        "-=0.5"
      );

    gsap.to(scrollArrowRef.current, {
      y: 10,
      opacity: 0.7,
      repeat: -1,
      yoyo: true,
      duration: 1.2,
      ease: "power1.inOut"
    });

    ScrollTrigger.create({
      trigger: heroRef.current,
      start: "5% top",
      onEnter: () => {
        gsap.to(scrollArrowRef.current, {
          opacity: 0,
          y: 20,
          duration: 0.5,
          ease: "power1.in"
        });
      },
      onLeaveBack: () => {
        gsap.to(scrollArrowRef.current, {
          opacity: 1,
          y: 0,
          duration: 0.5,
          ease: "power1.out"
        });
      }
    });

    gsap.to(textRef.current, {
      scrollTrigger: {
        trigger: heroRef.current,
        start: "top top",
        end: "bottom top",
        scrub: true
      },
      y: 100,
      opacity: 0.7
    });

    gsap.to(imageRef.current, {
      scrollTrigger: {
        trigger: heroRef.current,
        start: "top top",
        end: "bottom top",
        scrub: true
      },
      scale: 1.05
    });
  };

  return (
    <section className="hero-section" ref={heroRef}>
      <div className="hero-section__content">
        <HeroContent
          textRef={textRef}
          titleGreenRef={titleGreenRef}
          titleBlueRef={titleBlueRef}
          descriptionRef={descriptionRef}
          buttonsRef={buttonsRef}
          handleOpenModal={handleOpenModal}
          scrollToNextSection={scrollToNextSection}
        />

        <HeroImage imageRef={imageRef} collegeImage={collegeImage} />
      </div>

      <div className="particles-container" ref={particlesRef}>
        <Particles
          id="tsparticles"
          init={particlesInit}
          options={{
            fullScreen: { enable: false },
            background: {
              color: {
                value: "transparent",
              },
            },
            fpsLimit: 60,
            particles: {
              color: {
                value: ["#3586ff", "#98c1ff", "#0056d2"],
              },
              links: {
                color: "#3586ff",
                distance: 150,
                enable: true,
                opacity: 0.3,
                width: 1,
              },
              move: {
                direction: "none",
                enable: true,
                outModes: {
                  default: "bounce",
                },
                random: false,
                speed: 1,
                straight: false,
              },
              number: {
                density: {
                  enable: true,
                  area: 800,
                },
                value: 60,
              },
              opacity: {
                value: 0.4,
              },
              shape: {
                type: "circle",
              },
              size: {
                value: { min: 1, max: 5 },
              },
            },
            detectRetina: true,
            interactivity: {
              events: {
                onHover: {
                  enable: true,
                  mode: "grab",
                },
                onClick: {
                  enable: true,
                  mode: "push",
                },
                resize: true,
              },
              modes: {
                grab: {
                  distance: 140,
                  links: {
                    opacity: 0.5,
                  },
                },
                push: {
                  quantity: 4,
                },
              },
            },
          }}
        />
      </div>

      <ScrollArrow
        scrollArrowRef={scrollArrowRef}
        scrollToNextSection={scrollToNextSection}
      />

      <SubmitDocumentsModal
        isOpen={isModalOpen}
        onClose={handleCloseModal}
      />
    </section>
  );
};

export default HeroSection;