import React, { useEffect, lazy, Suspense } from 'react';
import Title from "../../components/ui/Title/Title";
import './About.scss';

import collegePhoto from '../../assets/img/img/college/College Photo.jpg';
import collegeBuilding from '../../assets/img/img/college/College-Photo.webp';

import WelcomeSection from './components/WelcomeSection';

const CollegeHistorySection = lazy(() => import('./components/CollegeHistorySection'));
const CollegeInfoSection = lazy(() => import('./components/CollegeInfoSection'));
const CollegeDocuments = lazy(() => import('./components/CollegeDocuments'));
const CollegeReviews = lazy(() => import('./components/CollegeReviews'));
const CallToAction = lazy(() => import('./components/CallToAction'));

const LoadingPlaceholder = () => (
  <div className="section-loading">
    <div className="section-loading__spinner"></div>
  </div>
);

const About = () => {
  useEffect(() => {
    const isMobile = window.innerWidth <= 768;
    const sections = document.querySelectorAll('.about-page > section');
    if (isMobile) {
      sections.forEach(section => {
        section.classList.add('section-visible');
      });
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.classList.add('section-visible');
            observer.unobserve(entry.target);
          }
        });
      },
      { rootMargin: '200px' }
    );
    sections.forEach(section => {
      observer.observe(section);
    });
    return () => {
      sections.forEach(section => {
        observer.unobserve(section);
      });
      observer.disconnect();
    };
  }, []);

  return (
    <div className="about-page">
      <Title title="О колледже" description="Информация о Донецком политехническом колледже, его истории, документах и отзывах студентов" />

      <WelcomeSection collegePhoto={collegePhoto} />

      <Suspense fallback={<LoadingPlaceholder />}>
        <CollegeHistorySection collegeBuilding={collegeBuilding} />
      </Suspense>

      <Suspense fallback={<LoadingPlaceholder />}>
        <CollegeInfoSection />
      </Suspense>

      <Suspense fallback={<LoadingPlaceholder />}>
        <CollegeDocuments />
      </Suspense>

      <Suspense fallback={<LoadingPlaceholder />}>
        <CollegeReviews />
      </Suspense>

      <Suspense fallback={<LoadingPlaceholder />}>
        <CallToAction />
      </Suspense>
    </div>
  );
};

export default About;